<script setup>
import { ref } from 'vue'; import {Head,Link,router,useForm} from '@inertiajs/vue3'; import AppLayout from '@/Layouts/AppLayout.vue'; import Button from '@/Components/UI/Button.vue'; import Icon from '@/Components/UI/Icon.vue'; import HrNav from '../Partials/HrNav.vue'; import {usePermissions} from '@/composables/usePermissions';
defineOptions({layout:AppLayout}); defineProps({leaves:Object,filterStatus:String,summary:Object,statuses:[Array,Object]}); const {can}=usePermissions(); const forms=ref({}); const actionForm=(uuid,action)=>forms.value[`${uuid}-${action}`]??=useForm({reason:''}); const act=(leave,action)=>actionForm(leave.uuid,action).post(`/administration/leave/${leave.uuid}/${action}`); const tone=(s)=>({PENDING:'bg-amber-50 text-amber-700',APPROVED:'bg-emerald-50 text-emerald-700',REJECTED:'bg-red-50 text-red-700',CANCELLED:'bg-gray-100 text-slate-500'}[s]);
</script>
<template><Head title="Congés"/><div class="space-y-5"><HrNav/><header class="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between"><div><p class="text-xs font-bold uppercase tracking-[.15em] text-amber-600">Demandes et décisions</p><h1 class="mt-1 font-heading text-3xl font-bold text-slate-800 dark:text-white">Congés</h1><p class="mt-2 text-sm text-slate-500">Circuit audité d’acceptation, de refus et d’annulation.</p></div><Button v-if="can('leave.create')" :as="Link" href="/administration/leave/create" size="rg"><Icon name="plus"/><span class="ms-2">Nouvelle demande</span></Button></header><nav class="flex flex-wrap gap-2"><Link href="/administration/leave?status=ALL" :class="['rounded-full px-3 py-2 text-xs font-bold',filterStatus==='ALL'?'bg-primary-600 text-white':'border border-gray-200 bg-white text-slate-500']">Toutes</Link><Link v-for="status in statuses" :key="status.value" :href="`/administration/leave?status=${status.value}`" :class="['rounded-full px-3 py-2 text-xs font-bold',filterStatus===status.value?'bg-primary-600 text-white':'border border-gray-200 bg-white text-slate-500']">{{status.label}} · {{summary[status.value]}}</Link></nav><section class="space-y-3"><article v-for="leave in leaves.data" :key="leave.uuid" class="rounded-xl border border-gray-200 bg-white shadow-sm dark:border-gray-900 dark:bg-gray-950"><div class="grid gap-4 p-5 lg:grid-cols-[minmax(0,1.2fr)_minmax(0,1fr)_auto]"><div><div class="flex flex-wrap items-center gap-2"><h2 class="font-bold text-slate-800 dark:text-white">{{leave.employee.name}}</h2><span :class="['rounded-full px-2.5 py-1 text-xs font-bold',tone(leave.status)]">{{leave.status_label}}</span></div><p class="mt-1 font-mono text-xs text-slate-400">{{leave.employee.employee_number}} · {{leave.uuid}}</p><p class="mt-3 text-sm text-slate-600 dark:text-slate-300">{{leave.reason}}</p></div><div class="grid grid-cols-2 gap-3 text-sm"><p><span class="block text-xs text-slate-400">Départ</span><strong>{{leave.starts_on}}</strong></p><p><span class="block text-xs text-slate-400">Retour</span><strong>{{leave.returns_on}}</strong></p><p><span class="block text-xs text-slate-400">Jours demandés</span><strong>{{leave.days_requested??'N/R'}}</strong></p><p><span class="block text-xs text-slate-400">Intérimaire</span><strong>{{leave.interim_employee?.name??'N/R'}}</strong></p></div><div class="flex items-start justify-end"><Button v-if="can('leave.print')" :as="Link" :href="`/administration/leave/${leave.uuid}/print`" icon size="rg" variant="white-outline" title="Imprimer"><Icon name="printer"/></Button></div></div><div v-if="leave.decision_reason||leave.cancel_reason" class="border-t border-gray-100 px-5 py-3 text-xs text-slate-500 dark:border-gray-900"><strong>Décision :</strong> {{leave.decision_reason||leave.cancel_reason}}<span v-if="leave.decided_by"> · {{leave.decided_by}}</span></div><div v-if="leave.status==='PENDING'" class="grid gap-3 border-t border-gray-200 bg-gray-50/60 p-4 dark:border-gray-900 dark:bg-gray-1000/30 lg:grid-cols-3"><form v-if="can('leave.approve')" class="flex gap-2" @submit.prevent="act(leave,'approve')"><input v-model="actionForm(leave.uuid,'approve').reason" maxlength="1000" placeholder="Note d’acceptation (facultative)" class="h-9 min-w-0 flex-1 rounded-lg border border-gray-200 px-3 text-xs dark:border-gray-800 dark:bg-gray-950"><Button size="sm" :disabled="actionForm(leave.uuid,'approve').processing">Accepter</Button></form><form v-if="can('leave.reject')" class="flex gap-2" @submit.prevent="act(leave,'reject')"><input v-model="actionForm(leave.uuid,'reject').reason" required maxlength="1000" placeholder="Motif du refus *" class="h-9 min-w-0 flex-1 rounded-lg border border-gray-200 px-3 text-xs dark:border-gray-800 dark:bg-gray-950"><Button size="sm" variant="danger" :disabled="actionForm(leave.uuid,'reject').processing">Refuser</Button></form><form v-if="can('leave.cancel')" class="flex gap-2" @submit.prevent="act(leave,'cancel')"><input v-model="actionForm(leave.uuid,'cancel').reason" required maxlength="1000" placeholder="Motif d’annulation *" class="h-9 min-w-0 flex-1 rounded-lg border border-gray-200 px-3 text-xs dark:border-gray-800 dark:bg-gray-950"><Button size="sm" variant="white-outline" :disabled="actionForm(leave.uuid,'cancel').processing">Annuler</Button></form></div></article><div v-if="!leaves.data.length" class="rounded-xl border border-dashed border-gray-300 bg-white py-14 text-center text-sm text-slate-400">Aucune demande dans cet état.</div></section></div></template>
